package browserlogin

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/airbytehq/airbyte-agent-cli/internal/client"
)

// stubSonar builds an httptest.Server that dispatches sonar bootstrap endpoints
// by path. Each handler is optional — unset handlers fail the test if hit.
type stubSonar struct {
	srv             *httptest.Server
	enrollmentCalls int32
	orgsCalls       int32
	appsCalls       int32
}

type sonarHandlers struct {
	enrollment http.HandlerFunc
	orgs       http.HandlerFunc
	apps       http.HandlerFunc
}

func newStubSonar(t *testing.T, h sonarHandlers) *stubSonar {
	t.Helper()
	s := &stubSonar{}
	mux := http.NewServeMux()
	mux.HandleFunc(APIBasePath+enrollmentStatusPath, func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&s.enrollmentCalls, 1)
		if h.enrollment == nil {
			t.Errorf("unexpected enrollment call")
			http.Error(w, "no handler", http.StatusInternalServerError)
			return
		}
		h.enrollment(w, r)
	})
	mux.HandleFunc(APIBasePath+organizationsListPath, func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&s.orgsCalls, 1)
		if h.orgs == nil {
			t.Errorf("unexpected organizations call")
			http.Error(w, "no handler", http.StatusInternalServerError)
			return
		}
		h.orgs(w, r)
	})
	mux.HandleFunc(APIBasePath+applicationsPath, func(w http.ResponseWriter, r *http.Request) {
		atomic.AddInt32(&s.appsCalls, 1)
		if h.apps == nil {
			t.Errorf("unexpected applications call")
			http.Error(w, "no handler", http.StatusInternalServerError)
			return
		}
		h.apps(w, r)
	})
	s.srv = httptest.NewServer(mux)
	t.Cleanup(s.srv.Close)
	return s
}

func writeJSON(t *testing.T, w http.ResponseWriter, status int, body interface{}) {
	t.Helper()
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(body); err != nil {
		t.Errorf("encode response: %v", err)
	}
}

func TestBootstrap_SingleOrgHappyPath(t *testing.T) {
	const orgID = "org-uuid-single"
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			if got := r.Header.Get("Authorization"); got != "Bearer access-token-abc" {
				t.Errorf("missing/wrong Authorization header: %q", got)
			}
			if got := r.Header.Get(headerAgentCLI); got != "test-version" {
				t.Errorf("missing X-ADP-Agent-CLI header: %q", got)
			}
			if got := r.Header.Get(headerOrgID); got != "" {
				t.Errorf("enrollment-status should NOT send X-Organization-Id, got %q", got)
			}
			writeJSON(t, w, 200, map[string]interface{}{
				"is_new_user":       false,
				"is_enrolled":       true,
				"is_instance_admin": false,
				"organization_id":   orgID,
			})
		},
		orgs: func(w http.ResponseWriter, r *http.Request) {
			if got := r.Header.Get(headerOrgID); got != orgID {
				t.Errorf("organizations missing X-Organization-Id; got %q", got)
			}
			writeJSON(t, w, 200, map[string]interface{}{
				"organizations": []map[string]string{
					{"id": orgID, "organization_name": "Solo"},
				},
				"is_instance_admin": false,
			})
		},
		apps: func(w http.ResponseWriter, r *http.Request) {
			if got := r.Header.Get(headerOrgID); got != orgID {
				t.Errorf("applications missing X-Organization-Id; got %q", got)
			}
			if r.Method != http.MethodPost {
				t.Errorf("applications wants POST, got %s", r.Method)
			}
			writeJSON(t, w, 201, map[string]string{
				"id":            "app-1",
				"name":          "Airbyte Agents",
				"client_id":     "ci",
				"client_secret": "cs",
			})
		},
	})

	res, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     s.srv.URL,
		AccessToken: "[REDACTED]",
		CLIVersion:  "test-version",
		HTTPClient:  s.srv.Client(),
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if res.ClientID != "ci" {
		t.Errorf("ClientID = %q, want %q", res.ClientID, "ci")
	}
	if res.ClientSecret != "cs" {
		t.Errorf("ClientSecret = %q, want %q", res.ClientSecret, "cs")
	}
	if res.OrganizationID != orgID {
		t.Errorf("OrganizationID = %q, want %q", res.OrganizationID, orgID)
	}
	if got := atomic.LoadInt32(&s.enrollmentCalls); got != 1 {
		t.Errorf("enrollment calls = %d, want 1", got)
	}
	if got := atomic.LoadInt32(&s.orgsCalls); got != 1 {
		t.Errorf("orgs calls = %d, want 1", got)
	}
	if got := atomic.LoadInt32(&s.appsCalls); got != 1 {
		t.Errorf("apps calls = %d, want 1", got)
	}
}

func TestBootstrap_MultiOrgWithOverride(t *testing.T) {
	const initialOrg = "org-initial"
	const explicit = "explicit-org-uuid"
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"is_enrolled":     true,
				"organization_id": initialOrg,
			})
		},
		// orgs handler intentionally left nil — must not be called.
		apps: func(w http.ResponseWriter, r *http.Request) {
			if got := r.Header.Get(headerOrgID); got != explicit {
				t.Errorf("applications got X-Organization-Id %q, want %q", got, explicit)
			}
			writeJSON(t, w, 200, map[string]string{
				"client_id":     "ci2",
				"client_secret": "cs2",
			})
		},
	})

	res, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:       s.srv.URL,
		AccessToken:   "tok",
		OrgIDOverride: explicit,
		HTTPClient:    s.srv.Client(),
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if res.OrganizationID != explicit {
		t.Errorf("OrganizationID = %q, want %q", res.OrganizationID, explicit)
	}
	if got := atomic.LoadInt32(&s.orgsCalls); got != 0 {
		t.Errorf("organizations endpoint should NOT be called when --org-id is set, got %d calls", got)
	}
}

func TestBootstrap_MultiOrgInteractivePicker(t *testing.T) {
	orgs := []map[string]string{
		{"id": "uuid-1", "organization_name": "Alpha"},
		{"id": "uuid-2", "organization_name": "Beta"},
		{"id": "uuid-3", "organization_name": "Gamma"},
	}
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"is_enrolled":     true,
				"organization_id": "uuid-1",
			})
		},
		orgs: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"organizations":     orgs,
				"is_instance_admin": false,
			})
		},
		apps: func(w http.ResponseWriter, r *http.Request) {
			if got := r.Header.Get(headerOrgID); got != "uuid-2" {
				t.Errorf("applications X-Organization-Id = %q, want uuid-2", got)
			}
			writeJSON(t, w, 201, map[string]string{
				"client_id":     "ci3",
				"client_secret": "cs3",
			})
		},
	})

	stderr := &bytes.Buffer{}
	res, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     s.srv.URL,
		AccessToken: "tok",
		Stdin:       bytes.NewBufferString("2\n"),
		Stderr:      stderr,
		StdinIsTTY:  true,
		HTTPClient:  s.srv.Client(),
	})
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if res.OrganizationID != "uuid-2" {
		t.Errorf("OrganizationID = %q, want uuid-2", res.OrganizationID)
	}
	if out := stderr.String(); !strings.Contains(out, "Alpha") || !strings.Contains(out, "Beta") || !strings.Contains(out, "Gamma") {
		t.Errorf("stderr missing org list: %q", out)
	}
}

func TestBootstrap_MultiOrgNonTTY(t *testing.T) {
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"is_enrolled":     true,
				"organization_id": "uuid-1",
			})
		},
		orgs: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"organizations": []map[string]string{
					{"id": "uuid-1", "organization_name": "Alpha"},
					{"id": "uuid-2", "organization_name": "Beta"},
				},
				"is_instance_admin": false,
			})
		},
	})

	_, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     s.srv.URL,
		AccessToken: "tok",
		StdinIsTTY:  false,
		HTTPClient:  s.srv.Client(),
	})
	if err == nil {
		t.Fatal("expected error when stdin is not a TTY and there are multiple orgs")
	}
	var apiErr *client.APIError
	if !errors.As(err, &apiErr) {
		t.Fatalf("error is not *client.APIError: %T %v", err, err)
	}
	if apiErr.Type != "validation_error" {
		t.Errorf("Type = %q, want validation_error", apiErr.Type)
	}
	if !strings.Contains(apiErr.Hint, "--org-id") {
		t.Errorf("Hint missing --org-id guidance: %q", apiErr.Hint)
	}
	if !strings.Contains(apiErr.Hint, "Alpha") || !strings.Contains(apiErr.Hint, "Beta") {
		t.Errorf("Hint missing org names: %q", apiErr.Hint)
	}
}

func TestBootstrap_Unenrolled(t *testing.T) {
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"is_enrolled": false,
			})
		},
	})

	_, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     s.srv.URL,
		AccessToken: "tok",
		HTTPClient:  s.srv.Client(),
	})
	if err == nil {
		t.Fatal("expected error for unenrolled user")
	}
	var apiErr *client.APIError
	if !errors.As(err, &apiErr) {
		t.Fatalf("error is not *client.APIError: %T %v", err, err)
	}
	if apiErr.Type != "validation_error" {
		t.Errorf("Type = %q, want validation_error", apiErr.Type)
	}
	if !strings.Contains(strings.ToLower(apiErr.Hint), "enrollment") {
		t.Errorf("Hint should mention enrollment, got %q", apiErr.Hint)
	}
	if apiErr.ExitCode() != client.ExitValidation {
		t.Errorf("ExitCode = %d, want %d", apiErr.ExitCode(), client.ExitValidation)
	}
}

func TestBootstrap_NetworkError(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	// Close immediately so all subsequent requests fail with connection refused.
	srv.Close()

	_, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     srv.URL,
		AccessToken: "tok",
		HTTPClient:  &http.Client{},
	})
	if err == nil {
		t.Fatal("expected error from closed server")
	}
	// Network errors must NOT be typed APIErrors — the caller's exit-code logic
	// should only fire for HTTP-status-based failures.
	var apiErr *client.APIError
	if errors.As(err, &apiErr) {
		t.Errorf("network error should not be *client.APIError, got %v", err)
	}
}

func TestBootstrap_ApplicationsForbiddenRemappedToValidation(t *testing.T) {
	s := newStubSonar(t, sonarHandlers{
		enrollment: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"is_enrolled":     true,
				"organization_id": "uuid-1",
			})
		},
		orgs: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 200, map[string]interface{}{
				"organizations": []map[string]string{
					{"id": "uuid-1", "organization_name": "Alpha"},
				},
				"is_instance_admin": false,
			})
		},
		apps: func(w http.ResponseWriter, r *http.Request) {
			writeJSON(t, w, 403, map[string]string{"detail": "subscription inactive"})
		},
	})

	_, err := Bootstrap(context.Background(), &BootstrapOptions{
		APIHost:     s.srv.URL,
		AccessToken: "tok",
		HTTPClient:  s.srv.Client(),
	})
	if err == nil {
		t.Fatal("expected error on 403 from applications")
	}
	var apiErr *client.APIError
	if !errors.As(err, &apiErr) {
		t.Fatalf("error is not *client.APIError: %T %v", err, err)
	}
	if apiErr.Type != "validation_error" {
		t.Errorf("403 should be remapped to validation_error, got %q", apiErr.Type)
	}
	if !strings.Contains(strings.ToLower(apiErr.Hint), "onboarding") {
		t.Errorf("Hint should mention onboarding, got %q", apiErr.Hint)
	}
}

package browserlogin

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/airbytehq/airbyte-agent-cli/internal/client"
)

// BootstrapResult is the trio of values written to ~/.airbyte-agent/settings.json
// after a successful browser login.
type BootstrapResult struct {
	ClientID       string
	ClientSecret   string
	OrganizationID string
}

// BootstrapOptions configures the Bootstrap call.
type BootstrapOptions struct {
	APIHost       string        // e.g. https://api.airbyte.ai (no trailing /api/v1)
	AccessToken   string        // Keycloak access token from RunOAuthFlow
	OrgIDOverride string        // value of --org-id flag, or "" for autodetect
	Stdin         io.Reader     // for the multi-org picker
	Stderr        io.Writer     // for the multi-org picker UI
	StdinIsTTY    bool          // caller signals whether interactive prompts are OK
	CLIVersion    string        // value of cmd.Version (defaults to "dev")
	HTTPClient    *http.Client  // test seam; nil → default
	Timeout       time.Duration // per-request timeout (default 30s if zero and HTTPClient nil)
}

const (
	APIBasePath           = "/api/v1"
	enrollmentStatusPath  = "/internal/account/enrollment-status"
	organizationsListPath = "/internal/account/organizations"
	applicationsPath      = "/internal/account/applications"
	headerOrgID           = "X-Organization-Id"
	headerAgentCLI        = "X-ADP-Agent-CLI"
)

// enrollmentStatusResponse mirrors sonar's EnrollmentStatusResponse, only the
// fields the CLI consumes. Extra fields are ignored by json.Unmarshal.
type enrollmentStatusResponse struct {
	IsNewUser        bool   `json:"is_new_user"`
	IsEnrolled       bool   `json:"is_enrolled"`
	IsInstanceAdmin  bool   `json:"is_instance_admin"`
	OrganizationID   string `json:"organization_id"`
	OrganizationName string `json:"organization_name,omitempty"`
}

// organizationListItem mirrors sonar's Organization (within OrganizationsListResponse).
type organizationListItem struct {
	ID               string `json:"id"`
	OrganizationName string `json:"organization_name"`
	FirstWorkspaceID string `json:"first_workspace_id,omitempty"`
}

// organizationsListResponse mirrors sonar's OrganizationsListResponse.
type organizationsListResponse struct {
	Organizations   []organizationListItem `json:"organizations"`
	IsInstanceAdmin bool                   `json:"is_instance_admin"`
}

// applicationResponse mirrors sonar's Application (subset).
type applicationResponse struct {
	ID           string `json:"id"`
	Name         string `json:"name"`
	ClientID     string `json:"client_id"`
	ClientSecret string `json:"client_secret"`
}

// Bootstrap calls the sonar bootstrap endpoints and returns the
// (client_id, client_secret, organization_id) trio.
//
// Sequence:
//  1. GET enrollment-status (no org header) → captures initialOrgID.
//  2. If OrgIDOverride is empty: GET organizations (with X-Organization-Id:
//     initialOrgID). 1 org → auto-select. >1 org → interactive picker (if
//     stdin is a TTY) or actionable error (if not).
//  3. POST applications (with X-Organization-Id: chosenOrgID) → returns
//     client_id + client_secret.
//
// All sonar HTTP error shapes are mapped to *client.APIError so the CLI's
// existing exit-code logic works without modification.
func Bootstrap(ctx context.Context, opts *BootstrapOptions) (*BootstrapResult, error) {
	if opts == nil {
		return nil, errors.New("bootstrap: nil options")
	}
	if opts.APIHost == "" {
		return nil, errors.New("bootstrap: APIHost required")
	}
	if opts.AccessToken == "" {
		return nil, errors.New("bootstrap: AccessToken required")
	}

	// Step 1: enrollment-status. The route auto-selects the first org when no
	// X-Organization-Id header is set, so we omit it here.
	var enr enrollmentStatusResponse
	if err := opts.do(ctx, http.MethodGet, enrollmentStatusPath, "", nil, &enr); err != nil {
		return nil, err
	}
	if !enr.IsEnrolled {
		return nil, client.NewValidationError(
			"complete onboarding at https://app.airbyte.ai before running login",
			"open the URL in a browser, finish the enrollment flow, then re-run airbyte-agent login",
		)
	}

	initialOrgID := enr.OrganizationID

	// Steps 2 & 3: pick organization (unless overridden via --org-id).
	chosenOrgID := opts.OrgIDOverride
	if chosenOrgID == "" {
		var orgs organizationsListResponse
		if err := opts.do(ctx, http.MethodGet, organizationsListPath, initialOrgID, nil, &orgs); err != nil {
			return nil, err
		}
		switch {
		case len(orgs.Organizations) == 0 && orgs.IsInstanceAdmin:
			return nil, &client.APIError{
				Type:       "validation_error",
				Message:    "instance admin login not supported from CLI; use a regular user account",
				StatusCode: 400,
			}
		case len(orgs.Organizations) == 0:
			return nil, &client.APIError{
				Type:       "validation_error",
				Message:    "no organizations found for this account",
				StatusCode: 400,
				Hint:       "complete onboarding at https://app.airbyte.ai before running login",
			}
		case len(orgs.Organizations) == 1:
			chosenOrgID = orgs.Organizations[0].ID
		default:
			if !opts.StdinIsTTY {
				return nil, &client.APIError{
					Type:       "validation_error",
					Message:    "you belong to multiple organizations and stdin is not a TTY",
					StatusCode: 400,
					Hint:       buildOrgListHint(orgs.Organizations),
				}
			}
			picked, err := pickOrganization(opts.Stdin, opts.Stderr, orgs.Organizations)
			if err != nil {
				return nil, err
			}
			chosenOrgID = picked
		}
	}

	// Step 4: POST applications.
	var app applicationResponse
	if err := opts.do(ctx, http.MethodPost, applicationsPath, chosenOrgID, nil, &app); err != nil {
		var apiErr *client.APIError
		if errors.As(err, &apiErr) {
			// 403 → likely Stigg-subscription gate fired.
			if apiErr.StatusCode == http.StatusForbidden {
				return nil, client.NewValidationError(
					"your organization is not enrolled or its subscription is inactive",
					"complete onboarding at https://app.airbyte.ai, then re-run airbyte-agent login",
				)
			}
			// 400 "specify target organization" — we already resolved an
			// orgID and put it in the X-Organization-Id header, so seeing
			// this means the server disagreed. Wrap so the user understands
			// they aren't missing a flag.
			if apiErr.StatusCode == http.StatusBadRequest &&
				strings.Contains(strings.ToLower(apiErr.Message), "specify target organization") {
				return nil, fmt.Errorf("server demanded an organization header even though one was supplied (org-id=%s): %w", chosenOrgID, err)
			}
		}
		return nil, err
	}

	return &BootstrapResult{
		ClientID:       app.ClientID,
		ClientSecret:   [REDACTED],
		OrganizationID: chosenOrgID,
	}, nil
}

// buildOrgListHint renders the available orgs for inclusion in an APIError
// Hint when stdin isn't a TTY and the user must rerun with --org-id.
func buildOrgListHint(orgs []organizationListItem) string {
	var sb strings.Builder
	sb.WriteString("re-run with --org-id <uuid>. Available organizations:")
	for _, o := range orgs {
		fmt.Fprintf(&sb, "\n  - %s (%s)", o.OrganizationName, o.ID)
	}
	return sb.String()
}

// do executes an authed request to opts.APIHost + APIBasePath + path. If `out`
// is non-nil, the response body is decoded into it. Non-2xx responses are
// returned as *client.APIError (matching the CLI's exit-code mapping).
func (o *BootstrapOptions) do(ctx context.Context, method, path, orgID string, body []byte, out interface{}) error {
	url := strings.TrimRight(o.APIHost, "/") + APIBasePath + path
	var reqBody io.Reader
	if body != nil {
		reqBody = bytes.NewReader(body)
	}
	req, err := http.NewRequestWithContext(ctx, method, url, reqBody)
	if err != nil {
		return fmt.Errorf("building %s request: %w", path, err)
	}
	req.Header.Set("Authorization", "Bearer "+o.AccessToken)
	req.Header.Set("Accept", "application/json")
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if orgID != "" {
		req.Header.Set(headerOrgID, orgID)
	}
	version := o.CLIVersion
	if version == "" {
		version = "dev"
	}
	req.Header.Set(headerAgentCLI, version)
	req.Header.Set("User-Agent", "airbyte-agent/"+version)

	httpClient := o.HTTPClient
	if httpClient == nil {
		timeout := o.Timeout
		if timeout == 0 {
			timeout = 30 * time.Second
		}
		httpClient = &http.Client{Timeout: timeout}
	}
	resp, err := httpClient.Do(req)
	if err != nil {
		return fmt.Errorf("calling %s: %w", path, err)
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("reading %s response: %w", path, err)
	}

	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		if out == nil || len(raw) == 0 {
			return nil
		}
		if err := json.Unmarshal(raw, out); err != nil {
			return fmt.Errorf("decoding %s response: %w", path, err)
		}
		return nil
	}

	// Non-2xx → APIError. Lift "detail" or "message" out of the body if JSON.
	apiErr := &client.APIError{
		StatusCode: resp.StatusCode,
		Type:       statusToType(resp.StatusCode),
		Message:    fmt.Sprintf("%s %s returned %d", method, path, resp.StatusCode),
	}
	if len(raw) > 0 && json.Valid(raw) {
		apiErr.Detail = json.RawMessage(raw)
		var lifted struct {
			Detail  string `json:"detail"`
			Message string `json:"message"`
		}
		if json.Unmarshal(raw, &lifted) == nil {
			if lifted.Detail != "" {
				apiErr.Message = lifted.Detail
			} else if lifted.Message != "" {
				apiErr.Message = lifted.Message
			}
		}
	}
	return apiErr
}

func statusToType(code int) string {
	switch {
	case code == 401:
		return "unauthorized"
	case code == 403:
		return "forbidden"
	case code == 400 || code == 422:
		return "validation_error"
	case code == 404:
		return "not_found"
	case code >= 500:
		return "server_error"
	default:
		return "api_error"
