// Package browserlogin holds the building blocks for the browser-based OAuth
// login flow (PKCE verifier/challenge, opaque state value, and — in later
// phases — the loopback callback server and end-to-end flow orchestration).
package browserlogin

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
)

// verifierByteLen is the raw entropy used to generate the PKCE code_verifier.
// 32 bytes encodes to 43 characters under base64-url-no-pad, which sits inside
// RFC 7636's 43-128 character range.
const verifierByteLen = 32

// GenerateVerifier returns a fresh PKCE code_verifier per RFC 7636.
// The verifier is base64-url-no-pad encoded random bytes; callers should treat
// the result as opaque and pass it through to Challenge as-is.
func GenerateVerifier() (string, error) {
	b := make([]byte, verifierByteLen)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// Challenge returns the S256 code_challenge for a given code_verifier per
// RFC 7636 §4.2: base64-url-no-pad of SHA-256(verifier).
func Challenge(verifier string) string {
	sum := sha256.Sum256([]byte(verifier))
	return base64.RawURLEncoding.EncodeToString(sum[:])
}

package browserlogin

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// pickOrganization renders a numbered list of orgs to stderr, reads a single
// integer from stdin, and returns the chosen org's ID.
//
// The caller is responsible for ensuring stdin is interactive — this function
// does not perform TTY detection (kept pure so it is trivially testable with
// bytes.Buffer in tests).
func pickOrganization(stdin io.Reader, stderr io.Writer, orgs []organizationListItem) (string, error) {
	if stdin == nil || stderr == nil {
		return "", errors.New("picker: stdin and stderr required")
	}
	if len(orgs) == 0 {
		return "", errors.New("picker: no organizations to choose from")
	}

	fmt.Fprintln(stderr, "You belong to multiple organizations. Choose one:")
	for i, o := range orgs {
		fmt.Fprintf(stderr, "  %d) %s  (%s)\n", i+1, o.OrganizationName, o.ID)
	}
	fmt.Fprintf(stderr, "Enter choice [1-%d]: ", len(orgs))

	reader := bufio.NewReader(stdin)
	raw, err := reader.ReadString('\n')
	if err != nil && err != io.EOF {
		return "", fmt.Errorf("reading choice: %w", err)
	}
	raw = strings.TrimSpace(raw)
	if raw == "" {
		return "", errors.New("picker: no input provided")
	}
	n, err := strconv.Atoi(raw)
	if err != nil {
		return "", fmt.Errorf("picker: invalid choice %q (not a number)", raw)
	}
	if n < 1 || n > len(orgs) {
		return "", fmt.Errorf("picker: choice %d out of range [1, %d]", n, len(orgs))
	}
	return orgs[n-1].ID, nil
}

package browserlogin

import (
	"crypto/rand"
	"encoding/base64"
)

// stateByteLen is the raw entropy used for the OAuth state parameter.
// 16 bytes encodes to 22 characters under base64-url-no-pad.
const stateByteLen = 16

// GenerateState returns a cryptographically random state value for OAuth flows.
// Callers should compare returned values with subtle.ConstantTimeCompare to
// avoid timing leaks.
func GenerateState() (string, error) {
	b := make([]byte, stateByteLen)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

package browserlogin

import (
	"context"
	"errors"
	"fmt"
	"html"
	"net"
	"net/http"
	"sync"
	"time"
)

// callbackResult carries the outcome of the single OAuth redirect we expect
// the loopback server to receive. Exactly one of (Code+State) or Err is set.
type callbackResult struct {
	Code  string
	State string
	Err   error
}

// loopback is a one-shot HTTP server bound to 127.0.0.1 on an ephemeral port.
// It accepts a single /callback request, decodes the OAuth response into a
// callbackResult, and signals waiters via the result channel. Subsequent
// requests after the first delivery are still served the success page but
// do not overwrite the captured result.
type loopback struct {
	// Port is the ephemeral port chosen by the kernel; the OAuth redirect_uri
	// embedded in the authorize URL must reference this port.
	Port int

	server *http.Server
	result chan callbackResult
	once   sync.Once
}

// startLoopback binds 127.0.0.1:0 and starts serving the /callback handler in
// a background goroutine. The caller is responsible for calling Shutdown when
// the flow is complete (whether successful or not).
//
// Binding only to 127.0.0.1 (never 0.0.0.0) is required by RFC 8252 §7.3: the
// authorization code must not be exposed to other hosts on the network.
func startLoopback() (*loopback, error) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return nil, fmt.Errorf("loopback listen: %w", err)
	}
	addr, ok := ln.Addr().(*net.TCPAddr)
	if !ok {
		_ = ln.Close()
		return nil, fmt.Errorf("loopback listener returned unexpected addr type %T", ln.Addr())
	}

	lb := &loopback{
		Port:   addr.Port,
		result: make(chan callbackResult, 1),
	}

	mux := http.NewServeMux()
	mux.HandleFunc(CallbackPath, lb.handleCallback)

	lb.server = &http.Server{
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	go func() {
		// Serve returns http.ErrServerClosed once Shutdown is invoked — that's
		// the expected exit, so we drop it silently.
		_ = lb.server.Serve(ln)
	}()

	return lb, nil
}

// handleCallback parses the OAuth response query string and delivers a
// callbackResult exactly once. The HTTP response is a minimal self-contained
// HTML page — no external assets — so it renders even with strict CSP, ad
// blockers, or air-gapped browsers.
func (l *loopback) handleCallback(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()

	if errStr := q.Get("error"); errStr != "" {
		desc := q.Get("error_description")
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		fmt.Fprintf(w,
			"<!doctype html><html><body><h1>Login failed</h1><p>%s: %s</p><p>You can close this window and return to the terminal.</p></body></html>",
			html.EscapeString(errStr), html.EscapeString(desc),
		)
		l.deliver(callbackResult{Err: fmt.Errorf("oauth error: %s: %s", errStr, desc)})
		return
	}

	code := q.Get("code")
	state := q.Get("state")
	if code == "" || state == "" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.WriteHeader(http.StatusBadRequest)
		fmt.Fprint(w,
			"<!doctype html><html><body><h1>Login failed</h1><p>Missing code or state in callback.</p><p>You can close this window and return to the terminal.</p></body></html>",
		)
		l.deliver(callbackResult{Err: errors.New("callback missing code or state")})
		return
	}

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	fmt.Fprint(w,
		"<!doctype html><html><body><h1>Login successful</h1><p>You can close this window and return to the terminal.</p></body></html>",
	)
	l.deliver(callbackResult{Code: code, State: state})
}

// deliver pushes a result onto the channel exactly once. Later callbacks (the
// browser sometimes retries) are silently ignored so we never block the
// handler goroutine.
func (l *loopback) deliver(r callbackResult) {
	l.once.Do(func() {
		l.result <- r
	})
}

// Wait blocks until the callback arrives or ctx is cancelled. The caller is
// responsible for invoking Shutdown afterwards (typically via defer at the
// call site that obtained the loopback).
func (l *loopback) Wait(ctx context.Context) (string, string, error) {
	select {
	case r := <-l.result:
		return r.Code, r.State, r.Err
	case <-ctx.Done():
		return "", "", ctx.Err()
	}
}

// Shutdown stops the loopback server. It is safe to call multiple times.
func (l *loopback) Shutdown() {
	if l == nil || l.server == nil {
		return
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	_ = l.server.Shutdown(shutdownCtx)
}

package browserlogin

import "time"

// DefaultKeycloakBase is the Keycloak realm authority that issues access
// tokens for production app.airbyte.ai users. Confirmed against sonar's
// frontend/.env.production (KEYCLOAK_URL + realm "_airbyte-cloud-users") and
// frontend/src/core/services/auth/KeycloakAuthProvider.tsx.
const DefaultKeycloakBase = "https://cloud.airbyte.com/auth/realms/_airbyte-cloud-users"

// DefaultClientID is the public Keycloak client id used by both the sonar
// web app and this CLI. Public client (no secret) — PKCE is required.
const DefaultClientID = "sonar-webapp"

// CallbackPath is the path the loopback server listens on for the OAuth
// redirect_uri. The full redirect_uri is http://127.0.0.1:<ephemeral>/callback.
const CallbackPath = "/callback"

// DefaultScopes are the OAuth/OIDC scopes requested at the authorize step.
// "offline_access" yields a refresh_token so future phases can renew silently.
const DefaultScopes = "openid email profile offline_access"

// DefaultTimeout caps the end-to-end browser flow (open → callback → token
// exchange). Three minutes mirrors common CLI OAuth conventions and is enough
// time to complete an IdP redirect chain (Google, SSO, etc.).
const DefaultTimeout = 3 * time.Minute

package browserlogin

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	"github.com/airbytehq/airbyte-agent-cli/internal/browser"
)

// Tokens is the result of a successful Keycloak login. Tokens are transient
// in-memory only — the caller (cmd/login.go in Phase 4) uses AccessToken to
// call sonar and then discards them. We do NOT persist Keycloak tokens to
// disk; the CLI's long-lived credential is the workspace API key, not the
// Keycloak refresh token.
type Tokens struct {
	AccessToken  string
	RefreshToken string
	IDToken      string
	TokenType    string
	ExpiresAt    time.Time
}

// Options configures RunOAuthFlow. Production callers may leave the struct
// zero-valued; defaults are derived from the Default* constants. Tests use
// OpenFunc and HTTPClient as injection seams.
type Options struct {
	// KeycloakBase is the Keycloak realm authority (no trailing slash, no
	// trailing /protocol/... path). Defaults to DefaultKeycloakBase.
	KeycloakBase string
	// ClientID is the public Keycloak client id. Defaults to DefaultClientID.
	ClientID string
	// Scopes is a space-separated OIDC scope string. Defaults to DefaultScopes.
	Scopes string
	// Timeout caps the entire flow. Defaults to DefaultTimeout.
	Timeout time.Duration
	// OpenFunc is a test seam for substituting the browser launcher.
	// Production callers should leave this nil — the package-level
	// browser.Open is used instead.
	OpenFunc func(string) error
	// HTTPClient is an optional override for the Keycloak token-exchange call.
	// Tests use this to point at an httptest.Server; nil means a default
	// client whose Timeout matches Options.timeout().
	HTTPClient *http.Client
	// Stderr receives user-facing messages emitted by the flow (currently only
	// the "couldn't open browser" fallback). nil → os.Stderr.
	Stderr io.Writer
}

func (o *Options) keycloakBase() string {
	if o != nil && o.KeycloakBase != "" {
		return o.KeycloakBase
	}
	return DefaultKeycloakBase
}

func (o *Options) clientID() string {
	if o != nil && o.ClientID != "" {
		return o.ClientID
	}
	return DefaultClientID
}

func (o *Options) scopes() string {
	if o != nil && o.Scopes != "" {
		return o.Scopes
	}
	return DefaultScopes
}

func (o *Options) timeout() time.Duration {
	if o != nil && o.Timeout > 0 {
		return o.Timeout
	}
	return DefaultTimeout
}

func (o *Options) openFunc() func(string) error {
	if o != nil && o.OpenFunc != nil {
		return o.OpenFunc
	}
	return browser.Open
}

func (o *Options) httpClient() *http.Client {
	if o != nil && o.HTTPClient != nil {
		return o.HTTPClient
	}
	return &http.Client{Timeout: o.timeout()}
}

func (o *Options) stderr() io.Writer {
	if o != nil && o.Stderr != nil {
		return o.Stderr
	}
	return os.Stderr
}

// tokenResponse mirrors the Keycloak OIDC token-endpoint JSON. The Error and
// ErrorDesc fields cover the RFC 6749 error response shape; both are empty on
// success.
type tokenResponse struct {
	AccessToken  string `json:"access_token"`
	RefreshToken string `json:"refresh_token"`
	IDToken      string `json:"id_token"`
	TokenType    string `json:"token_type"`
	ExpiresIn    int    `json:"expires_in"`
	Error        string `json:"error"`
	ErrorDesc    string `json:"error_description"`
}

// RunOAuthFlow performs a complete browser-based Keycloak login using PKCE
// (S256). On success the user has completed the redirect, the loopback
// captured the authorization code, and we have exchanged it at the Keycloak
// token endpoint. The returned Tokens are valid only for the lifetime of the
// caller — nothing is persisted.
func RunOAuthFlow(ctx context.Context, opts *Options) (*Tokens, error) {
	verifier, err := GenerateVerifier()
	if err != nil {
		return nil, fmt.Errorf("pkce verifier: %w", err)
	}
	challenge := Challenge(verifier)
	state, err := GenerateState()
	if err != nil {
		return nil, fmt.Errorf("oauth state: %w", err)
	}

	lb, err := startLoopback()
	if err != nil {
		return nil, err
	}
	defer lb.Shutdown()

	flowCtx, cancel := context.WithTimeout(ctx, opts.timeout())
	defer cancel()

	redirectURI := fmt.Sprintf("http://127.0.0.1:%d%s", lb.Port, CallbackPath)
	authorizeURL := buildAuthorizeURL(
		opts.keycloakBase(), opts.clientID(), redirectURI,
		opts.scopes(), state, challenge,
	)

	// If the browser launcher itself fails (no browser binary, headless machine,
	// etc.) we still wait on the loopback so the user can paste the URL manually,
	// but we surface the failure and print the URL so they know what to do
	// instead of staring at a frozen terminal for three minutes.
	if err := opts.openFunc()(authorizeURL); err != nil {
		fmt.Fprintf(opts.stderr(),
			"could not auto-open browser (%v).\nPaste this URL manually:\n  %s\n",
			err, authorizeURL)
	}

	code, returnedState, err := lb.Wait(flowCtx)
	if err != nil {
		return nil, fmt.Errorf("waiting for browser callback: %w", err)
	}
	if subtle.ConstantTimeCompare([]byte(state), []byte(returnedState)) != 1 {
		return nil, errors.New("oauth state mismatch - possible CSRF or replay")
	}

	tokens, err := exchangeCodeForTokens(flowCtx, opts, code, verifier, redirectURI)
	if err != nil {
		return nil, err
	}
	return tokens, nil
}

// buildAuthorizeURL composes the Keycloak /protocol/openid-connect/auth URL
// with all PKCE + OIDC parameters URL-encoded.
func buildAuthorizeURL(base, clientID, redirectURI, scopes, state, challenge string) string {
	q := url.Values{}
	q.Set("response_type", "code")
	q.Set("client_id", clientID)
	q.Set("redirect_uri", redirectURI)
	q.Set("scope", scopes)
	q.Set("state", state)
	q.Set("code_challenge", challenge)
	q.Set("code_challenge_method", "S256")
	return strings.TrimRight(base, "/") + "/protocol/openid-connect/auth?" + q.Encode()
}

// exchangeCodeForTokens POSTs the authorization code + PKCE verifier to
// Keycloak's token endpoint and decodes the response.
func exchangeCodeForTokens(ctx context.Context, opts *Options, code, verifier, redirectURI string) (*Tokens, error) {
	body := url.Values{}
	body.Set("grant_type", "authorization_code")
	body.Set("code", code)
	body.Set("redirect_uri", redirectURI)
	body.Set("client_id", opts.clientID())
	body.Set("code_verifier", verifier)

	tokenURL := strings.TrimRight(opts.keycloakBase(), "/") + "/protocol/openid-connect/token"
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenURL, strings.NewReader(body.Encode()))
	if err != nil {
		return nil, fmt.Errorf("build token request: %w", err)
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("Accept", "application/json")

	resp, err := opts.httpClient().Do(req)
	if err != nil {
		return nil, fmt.Errorf("token exchange: %w", err)
	}
	defer resp.Body.Close()

	raw, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading token response: %w", err)
	}

	var tr tokenResponse
	if jsonErr := json.Unmarshal(raw, &tr); jsonErr != nil {
		// Surface status code in the wrapper so non-JSON 5xx pages are
		// debuggable even though we can't parse them.
		return nil, fmt.Errorf("parsing token response (status %d): %w", resp.StatusCode, jsonErr)
	}
	if resp.StatusCode != http.StatusOK || tr.Error != "" {
		if tr.Error != "" {
			return nil, fmt.Errorf("token endpoint error %s: %s", tr.Error, tr.ErrorDesc)
		}
		return nil, fmt.Errorf("token endpoint returned %d", resp.StatusCode)
	}

	return &Tokens{
		AccessToken:  [REDACTED],
		RefreshToken: [REDACTED],
		IDToken:      tr.IDToken,
		TokenType:    tr.TokenType,
		ExpiresAt:    time.Now().Add(time.Duration(tr.ExpiresIn) * time.Second),
	}, nil
}

package auth

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestTokenManager_Exchange(t *testing.T) {
	var received tokenRequest
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Errorf("expected POST, got %s", r.Method)
		}
		if r.URL.Path != tokenPath {
			t.Errorf("expected path %s, got %s", tokenPath, r.URL.Path)
		}
		if ct := r.Header.Get("Content-Type"); ct != "application/json" {
			t.Errorf("expected Content-Type application/json, got %s", ct)
		}

		if err := json.NewDecoder(r.Body).Decode(&received); err != nil {
			t.Fatalf("decoding request: %v", err)
		}

		resp := tokenResponse{
			AccessToken: "[REDACTED]",
			TokenType:   "bearer",
			ExpiresIn:   1200,
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "my-id", ClientSecret: "my-secret"}
	tm := NewTokenManager(server.URL, "", creds)

	token, err := tm.GetToken()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if token != "test-token-123" {
		t.Errorf("token = %q, want %q", token, "test-token-123")
	}
	if received.ClientID != "my-id" {
		t.Errorf("received ClientID = %q, want %q", received.ClientID, "my-id")
	}
	if received.ClientSecret != "my-secret" {
		t.Errorf("received ClientSecret = %q, want %q", received.ClientSecret, "my-secret")
	}
}

func TestTokenManager_OrgIDHeader(t *testing.T) {
	var gotOrgID string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotOrgID = r.Header.Get("X-Organization-Id")
		resp := tokenResponse{AccessToken: "tok", ExpiresIn: 1200}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "id", ClientSecret: "secret"}
	tm := NewTokenManager(server.URL, "org-abc", creds)

	_, err := tm.GetToken()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if gotOrgID != "org-abc" {
		t.Errorf("X-Organization-Id = %q, want %q", gotOrgID, "org-abc")
	}
}

func TestTokenManager_Caching(t *testing.T) {
	var callCount atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		callCount.Add(1)
		resp := tokenResponse{AccessToken: "[REDACTED]", ExpiresIn: 1200}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "id", ClientSecret: "secret"}
	tm := NewTokenManager(server.URL, "", creds)

	for i := 0; i < 5; i++ {
		token, err := tm.GetToken()
		if err != nil {
			t.Fatalf("call %d: unexpected error: %v", i, err)
		}
		if token != "cached-token" {
			t.Errorf("call %d: token = %q, want %q", i, token, "cached-token")
		}
	}

	if count := callCount.Load(); count != 1 {
		t.Errorf("server called %d times, want 1", count)
	}
}

func TestTokenManager_RefreshOnExpiry(t *testing.T) {
	var callCount atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		count := callCount.Add(1)
		resp := tokenResponse{
			AccessToken: "token-" + string(rune('0'+count)),
			ExpiresIn:   1200,
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "id", ClientSecret: "secret"}
	tm := NewTokenManager(server.URL, "", creds)

	_, err := tm.GetToken()
	if err != nil {
		t.Fatalf("first call: %v", err)
	}

	tm.mu.Lock()
	tm.expiresAt = time.Now().Add(30 * time.Second)
	tm.mu.Unlock()

	_, err = tm.GetToken()
	if err != nil {
		t.Fatalf("second call: %v", err)
	}

	if count := callCount.Load(); count != 2 {
		t.Errorf("server called %d times, want 2", count)
	}
}

func TestTokenManager_ConcurrentAccess(t *testing.T) {
	var callCount atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		callCount.Add(1)
		time.Sleep(10 * time.Millisecond)
		resp := tokenResponse{AccessToken: "[REDACTED]", ExpiresIn: 1200}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(resp)
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "id", ClientSecret: "secret"}
	tm := NewTokenManager(server.URL, "", creds)

	var wg sync.WaitGroup
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			token, err := tm.GetToken()
			if err != nil {
				t.Errorf("unexpected error: %v", err)
				return
			}
			if token != "concurrent-token" {
				t.Errorf("token = %q, want %q", token, "concurrent-token")
			}
		}()
	}
	wg.Wait()

	if count := callCount.Load(); count != 1 {
		t.Errorf("server called %d times, want 1 (mutex should prevent concurrent exchanges)", count)
	}
}

func TestTokenManager_ServerError(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
		_, _ = w.Write([]byte(`{"detail": "server broke"}`))
	}))
	defer server.Close()

	creds := &Credentials{ClientID: "id", ClientSecret: "secret"}
	tm := NewTokenManager(server.URL, "", creds)

	_, err := tm.GetToken()
	if err == nil {
		t.Fatal("expected error, got nil")
	}
}

package auth

import (
	"os"
	"path/filepath"
	"testing"
)

const validSettingsJSON = `{
  "settings": {
    "credentials": {
      "client_id": "file-id",
      "client_secret": "file-secret"
    },
    "organization_id": "file-org"
  }
}`

func writeSettings(t *testing.T, tmpDir, body string) {
	t.Helper()
	dir := filepath.Join(tmpDir, ".airbyte-agent")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		t.Fatalf("creating dir: %v", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "settings.json"), []byte(body), 0o600); err != nil {
		t.Fatalf("writing settings: %v", err)
	}
}

func TestResolveSettings_EnvVars(t *testing.T) {
	tests := []struct {
		name      string
		clientID  string
		clientSec string
		orgID     string
		wantErr   bool
	}{
		{name: "all three env vars set", clientID: "env-id", clientSec: "env-secret", orgID: "env-org"},
		{name: "missing client_id", clientSec: "env-secret", orgID: "env-org", wantErr: true},
		{name: "missing client_secret", clientID: "env-id", orgID: "env-org", wantErr: true},
		{name: "missing organization_id", clientID: "env-id", clientSec: "env-secret", wantErr: true},
		{name: "all empty", wantErr: true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Setenv("HOME", t.TempDir())
			t.Setenv("AIRBYTE_CLIENT_ID", tt.clientID)
			t.Setenv("AIRBYTE_CLIENT_SECRET", tt.clientSec)
			t.Setenv("AIRBYTE_ORGANIZATION_ID", tt.orgID)

			s, err := ResolveSettings()
			if tt.wantErr {
				if err == nil {
					t.Fatal("expected error, got nil")
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if s.Credentials.ClientID != tt.clientID {
				t.Errorf("ClientID = %q, want %q", s.Credentials.ClientID, tt.clientID)
			}
			if s.Credentials.ClientSecret != tt.clientSec {
				t.Errorf("ClientSecret = %q, want %q", s.Credentials.ClientSecret, tt.clientSec)
			}
			if s.OrganizationID != tt.orgID {
				t.Errorf("OrganizationID = %q, want %q", s.OrganizationID, tt.orgID)
			}
		})
	}
}

func TestResolveSettings_EnvTakesPrecedence(t *testing.T) {
	tmpDir := t.TempDir()
	t.Setenv("HOME", tmpDir)
	writeSettings(t, tmpDir, validSettingsJSON)

	t.Setenv("AIRBYTE_CLIENT_ID", "env-id")
	t.Setenv("AIRBYTE_CLIENT_SECRET", "env-secret")
	t.Setenv("AIRBYTE_ORGANIZATION_ID", "env-org")

	s, err := ResolveSettings()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if s.Credentials.ClientID != "env-id" {
		t.Errorf("expected env client_id, got %q", s.Credentials.ClientID)
	}
	if s.OrganizationID != "env-org" {
		t.Errorf("expected env organization_id, got %q", s.OrganizationID)
	}
}

func TestResolveSettings_PartialEnvFallsBackToFile(t *testing.T) {
	tmpDir := t.TempDir()
	t.Setenv("HOME", tmpDir)
